local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3b0ab5c67453f7fb"] = { "Le radici e le felci parlano bene di te, piccol<o/a>. Ho molti nomi, ma rispondo a pochi. Tu puoi chiamarmi Rethiel.\n\nE devi ascoltare... perché queste terre piangono per ferite infette, e io ti affido il compito di guarirle.", "." },
  ["3b0b244bd6b66153"] = { "Ce l'abbiamo fatta! Vittoria all'⟦Alliance=Alleanza⟧!", "." },
  ["3b102456f3892c77"] = { "Interessante, continua, per favore.", "." },
  ["3b1b4da7b982c88f"] = { "Vorrei parlare con gli spiriti, Tiev.", "." },
  ["3b1ba3f2dc3097c0"] = { "I Thunderbrew gestiscono un'ottima locanda a Kharanos che porta il loro nome. Fermati per una pinta e un po' di riposo.", "." },
  ["3b1e0d6cf644af4e"] = { "Vermi affamati banchetteranno con la tua carne in putrefazione.", "." },
  ["3b2297d1be2504eb"] = { "Forse riesco ad aggiustarlo, papà. Fammi dare un'occhiata.", "." },
  ["3b23e4ad29c1cb3b"] = { "Combattete, e oggi vinceremo!", "." },
  ["3b2ad2fb07d91d1b"] = { "Sottomettiti alla volontà del Signore del Vento e implora il suo perdono!", "." },
  ["3b2d9a29f292c435"] = { "Le pagine del diario sembrano piene di informazioni su commerci, acquirenti e altre faccende d'affari.", "." },
  ["3b2ec623d94e22a8"] = { "Quanti cibi cucinati ha raccolto finora l'⟦Alliance=Alleanza⟧?", "." },
  ["3b39404aa40da438"] = { "Eccomi! Venite a prendermi, smidollati dell'Alleanza!", "." },
  ["3b416017e3d9376b"] = { "Soldati dei Piccatonante, il vostro generale è sotto attacco! Mi serve aiuto! Presto! Presto! Uccidete questi cani rognosi dei Lupi Bianchi.", "." },
  ["3b437d1e8126578b"] = { "Paladini... Ho sentito dire che avete molte vite. Fatemele vedere.", "." },
  ["3b46baef7a1f8661"] = { "Deponete le armi, le vostre faide non hanno posto qui!", "." },
  ["3b52007e5b735b78"] = { "Questo raggio di luce lunare superiore ti porterà a Darnassus.", "." },
  ["3b61290f604a32ec"] = { "L'odio di Nefarius mi ha reso più forte che mai! Avreste dovuto fuggire finché potevate, mortali! La furia dei ⟦Blackrock=Roccianera⟧ mi scorre nelle vene!", "." },
  ["3b62c8ebbbe45c6a"] = { "Molte delle forniture che servono agli artigiani si trovano in giro per il mondo. Per quelle che non si trovano, offro una scelta limitata a un prezzo onesto.", "." },
  ["3b657590c0c3982c"] = { "Meraviglioso. Semplicemente meraviglioso. Sei un'ispirazione per tutti noi, {name}.", "." },
  ["3b65aafc6366e9f3"] = { "Tu! {race}! Vieni qui. <grugnito>\n\nIl tempo stringe, e la mia fine <grugnito> è vicina. ⟦Mangletooth=Squarciadenti⟧ vincerà, vedrai. <grugnito>\n\nLa mia cattura può ancora aiutare <grugnito> il mio popolo. La tribù dei ⟦Razormane=Chiomaguzza⟧ è più potente dei Mantotergo!\n\nL'⟦Horde=Orda⟧ vuole scoprire chi guida le incursioni contro la sua gente. Tu <grugnito> aiuterai ⟦Mangletooth=Squarciadenti⟧ in cambio delle informazioni che solo io conosco. ⟦Mangletooth=Squarciadenti⟧ può aiutarti! <grugnito> Ma tu devi aiutare ⟦Mangletooth=Squarciadenti⟧.", "." },
  ["3b667ec322161c3a"] = { "Sto scomparendo da {name}.", "." },
  ["3b7adc87be6324a3"] = { "Lo giuro... se Quint prova ancora una volta a infilarmi addosso un verme da pesca, gli abbatto l'albero con la mia spada non poi così arrugginita.", "." },
  ["3b7e7e09b4433835"] = { "E l'ha fatto?", "." },
  ["3b7e94ab95396667"] = { "Esatto. Hai ascoltato! Questo pesciolino è davvero una creatura terribile, opera mia. Quando mi rilasso mi piace pensare ai pescatori sfortunati che si sono imbattuti in questo pesciolino e sono stati divorati in un boccone. Scommetto che sono rimasti piuttosto sorpresi!\n\n<Azuregos ride.>", "." },
  ["3b83d9c9619c45cd"] = { "Li eseguirò con piacere, {name}!", "." },
  ["3b8eb65dbc4ba78d"] = { "Ora sei <pronto/pronta> per imparare le finezze della concia delle pelli di kodo. Cominciamo...", "." },
  ["3b8fc6ec339db1e7"] = { "Feccia come voi non vale nemmeno il mio tempo. Distruggeteli, branco mio!", "." },
  ["3b9089c491b79492"] = { "Quanti lingotti di metallo ha raccolto finora l'⟦Alliance=Alleanza⟧?", "." },
  ["3b91df635183bf58"] = { "Dobbiamo uccidere altri troll! Uccidine abbastanza e farò saltare la porta del capo dei troll!", "." },
  ["3b94ee06e8676e2e"] = { "%s crolla, ma il corpo spezzato si rialza!", "." },
  ["3b94f9aac673cf9f"] = { "<La collana d'argento che hai tra le mani luccica dolcemente mentre la esamini. La piccola falce di luna richiama la stessa Madre Luna.\r\n\nGirando la collana trovi una piccola iscrizione: \"Ti vogliamo bene, Maliynn\". Forse appartiene a Maliynn, ad Astranaar?>", "." },
  ["3ba6a37f99b5c574"] = { "Salute, cittadino. Come posso aiutarti oggi?", "." },
  ["3bade6d222eee3a5"] = { "Puoi contare su di me, Jeztor.", "." },
  ["3bb49b77f727d647"] = { "Sappi questo: Eranikus non desidera altro che essere portato su Azeroth dal Sogno. Una volta uscito, non si fermerà davanti a nulla pur di distruggere la mia manifestazione fisica. Questo, però, è l'unico modo in cui potresti recuperare il frammento dello scettro.", "." },
  ["3bc278a509a38933"] = { "Sarà un vero piacere aiutarti a muovere i primi passi! Fammi prendere il filatoio e cominciamo...", "." },
  ["3bcebb4f7703b915"] = { "Ti prego, spiegami come funziona lo scettro.", "." },
  ["3bda17948348b1a4"] = { "Presto sarai pront<o/a>, {name}.", "." },
  ["3bdd17cacbc31043"] = { "La Royal Apothecary Society ha poca pazienza con gli sciocchi, e io pure. Forse la prossima volta che parleremo dei miei destrieri sarai <considerato/considerata> amic<o/a> di ⟦Undercity=Sepulcra⟧. Fino ad allora...", "." },
  ["3bde261437bc081e"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ lo conquisterà!", "." },
  ["3be17a1cbc1d52c9"] = { "Manco da tanto tempo... è meglio che torni.", "." },
  ["3beb9074c1d52e80"] = { "Hai servito la nostra causa con grande lealtà, {name}. Permettimi di donarti una fonte inesauribile della nostra quintessenza elementale.", "." },
  ["3bf23abbde4321b5"] = { "Vivo per servire la Madre Terra e l'⟦Horde=Orda⟧, ma non posso fare a meno di sentirmi un po' in ansia ora che abbiamo raccolto tutto ciò che ci serve. Almeno abbiamo un po' di tempo prima che l'⟦Alliance=Alleanza⟧ finisca la sua raccolta. Dopo, tutto verrà spedito alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e probabilmente la guerra seguirà non molto tempo dopo.", "." },
  ["3bf437e659e2fa4a"] = { "Lui morto.", "." },
  ["3bf4b814a8d37883"] = { "Una banca? Be', la banca più vicina da queste parti è la Stormwind Counting House. È poco più avanti lungo la strada, a ⟦Stormwind=Roccavento⟧, non lontano dai cancelli.", "." },
  ["3bfbce42cb049112"] = { "Forse avrei fatto meglio a comprarne un po' da Faruza?", "." },
})
